import sys
stdin = sys.stdin.readline
stdout = sys.stdout.write

def next_int(): return int(stdin().strip())
def next_array(): return list(map(int, stdin().split()))

def solve():
    h, w, m = next_array()
    color_count = {}
    ops = []
    for i in range(m):
        t, a, x = next_array()
        ops.append([t, a - 1, x])

    r = h
    c = w
    row_visited = [False] * h
    col_visited = [False] * w
    for i in range(m - 1, -1, -1):
        t, a, x = ops[i]
        if t == 1:
            if not row_visited[a]:
                row_visited[a] = True
                if x not in color_count:
                    color_count[x] = 0
                color_count[x] += c
                r -= 1
        elif t == 2:
            if not col_visited[a]:
                col_visited[a] = True
                if x not in color_count:
                    color_count[x] = 0
                color_count[x] += r
                c -= 1

    for color in sorted(color_count.keys()):
        stdout(f"{color} {color_count[color]}\n")

if __name__ == "__main__":
    solve()
